            'emails.preview_only_no_campaign_queue_log_entry_or_real_unique_coupon_is_crea' => ['group' => 'emails', 'label' => 'Preview only. No campaign queue, log entry, or real unique coupon is created.', 'default' => 'Preview only. No campaign queue, log entry, or real unique coupon is created.', 'es_ES' => 'Solo vista previa. No se crea ninguna entrada de cola o registro de campaña ni ningún cupón único real.', 'ru_RU' => 'Только предпросмотр. Очередь кампании, запись журнала и реальный уникальный купон не создаются.', 'fr_FR' => 'Aperçu uniquement. Aucune file de campagne, entrée de journal ni coupon unique réel n’est créé.', 'de_DE' => 'Nur Vorschau. Es werden keine Kampagnenwarteschlange, kein Protokolleintrag und kein echter eindeutiger Gutschein erstellt.', 'et' => 'Ainult eelvaade. Kampaania järjekorda ega logikirjet ei looda ning tegelikku unikaalset kupongi ei genereerita.', 'da_DK' => 'Kun forhåndsvisning. Der oprettes ingen kampagnekø, logpost eller rigtig unik kupon.', 'nl_NL' => 'Alleen voorbeeld. Er wordt geen campagnewachtrij, logboekvermelding of echte unieke coupon aangemaakt.', 'sv_SE' => 'Endast förhandsvisning. Ingen kampanjkö, loggpost eller verklig unik kupong skapas.', 'fi' => 'Vain esikatselu. Kampanjajonoa, lokimerkintää tai oikeaa yksilöllistä kuponkia ei luoda.', 'it_IT' => 'Solo anteprima. Non vengono creati elementi nella coda della campagna, registri o coupon univoci reali.', 'pt_PT' => 'Apenas pré-visualização. Não é criada qualquer fila de campanha, entrada de registo ou cupão único real.', 'pt_BR' => 'Apenas pré-visualização. Nenhuma fila é criada de campanha, entrada de registro ou cupom único real.', 'sk_SK' => 'Iba náhľad. Nevytvorí sa front kampane, záznam v protokole ani skutočný jedinečný kupón.', 'pl_PL' => 'Tylko podgląd. Kolejka kampanii, wpis w dzienniku ani rzeczywisty unikalny kupon nie zostaną utworzone.', 'cs_CZ' => 'Pouze náhled. Nevytvoří se fronta kampaně, záznam protokolu ani skutečný jedinečný kupón.', 'cs' => 'Pouze náhled. Nevytvoří se fronta kampaně, záznam protokolu ani skutečný jedinečný kupón.', 'sl_SI' => 'Samo predogled. V čakalni vrsti kampanje ali dnevniku ne bo ustvarjen noben zapis, prav tako ne bo ustvarjen pravi enolični kupon.', 'hr_HR' => 'Samo pregled. Ne stvaraju se zapis u redu kampanje, zapisnik ni stvarni jedinstveni kupon.', 'ro_RO' => 'Doar previzualizare. Nu se creează nicio coadă de campanie, înregistrare în jurnal sau cupon unic real.', 'hu_HU' => 'Csak előnézet. Nem jön létre kampánysor, naplóbejegyzés vagy valódi egyedi kupon.', 'bg_BG' => 'Само преглед. Не се създават опашка за кампания, запис в дневника или реален уникален купон.', 'lt_LT' => 'Tik peržiūra. Kampanijos eilė, žurnalo įrašas ar tikras unikalus kuponas nesukuriamas.', 'lv' => 'Tikai priekšskatījums. Kampaņas rinda, žurnāla ieraksts vai īsts unikāls kupons netiek izveidots.', 'no_NO' => 'Kun forhåndsvisning. Det opprettes ingen kampanjekø, loggoppføring eller ekte unik kupong.', 'is_IS' => 'Aðeins forskoðun. Engin herferð er sett í biðröð, engin færslu er bætt í skrá og enginn raunverulegur einstakur afsláttarkóði er búinn til.', 'el' => 'Μόνο προεπισκόπηση. Δεν δημιουργείται εγγραφή ουράς καμπάνιας, καταγραφή ή πραγματικό μοναδικό κουπόνι.', 'ga_IE' => 'Réamhamharc amháin. Ní chruthaítear taifead sa scuaine feachtais, iontráil loga ná fíorchúpón uathúil.', 'mt_MT' => 'Previżjoni biss. Ma jinħolqu l-ebda kju tal-kampanja, rekord tal-log jew kupun uniku reali.'],
