            'emails.test.please_enter_a_valid_test_email_address' => ['group' => 'emails', 'label' => 'Please enter a valid test email address.', 'default' => 'Please enter a valid test email address.', 'es_ES' => 'Introduce una dirección de correo de prueba válida.', 'ru_RU' => 'Введите корректный адрес для тестового письма.', 'et' => 'Palun sisesta kehtiv test-e-posti aadress.', 'de_DE' => 'Bitte geben Sie eine gültige Test-E-Mail-Adresse ein.', 'fr_FR' => 'Saisissez une adresse e-mail de test valide.', 'da_DK' => 'Indtast en gyldig e-mailadresse til testen.', 'nl_NL' => 'Voer een geldig e-mailadres voor de test in.', 'sv_SE' => 'Ange en giltig e-postadress för testet.', 'fi' => 'Anna kelvollinen testisähköpostiosoite.', 'it_IT' => 'Inserisci un indirizzo email di prova valido.', 'pt_PT' => 'Introduza um endereço de email de teste válido.', 'pt_BR' => 'Introduza um endereço de e-mail de teste válido.', 'sk_SK' => 'Zadajte platnú testovaciu e-mailovú adresu.', 'pl_PL' => 'Wprowadź prawidłowy testowy adres e-mail.', 'cs_CZ' => 'Zadejte platnou e-mailovou adresu pro test.', 'cs' => 'Zadejte platnou e-mailovou adresu pro test.', 'sl_SI' => 'Vnesite veljaven e-poštni naslov za testiranje.', 'hr_HR' => 'Unesite valjanu e-adresu za testiranje.', 'ro_RO' => 'Introduceți o adresă de e-mail de test validă.', 'hu_HU' => 'Adjon meg érvényes teszt e-mail-címet.', 'bg_BG' => 'Моля, въведете валиден тестов имейл адрес.', 'lt_LT' => 'Įveskite galiojantį bandomojo el. pašto adresą.', 'lv' => 'Ievadiet derīgu testa e-pasta adresi.', 'no_NO' => 'Skriv inn en gyldig e-postadresse for testing.', 'is_IS' => 'Sláðu inn gilt netfang fyrir prufu.', 'el' => 'Εισαγάγετε μια έγκυρη διεύθυνση δοκιμαστικού email.', 'ga_IE' => 'Cuir seoladh ríomhphoist tástála bailí isteach.', 'mt_MT' => 'Daħħal indirizz email validu għat-test.'],
            'emails.test.smtp_test_email_could_not_be_sent_please_check_host_port_encryption_and_' => ['group' => 'emails', 'label' => 'SMTP test email could not be sent. Please check host, port, encryption and authentication settings.', 'default' => 'SMTP test email could not be sent. Please check host, port, encryption and authentication settings.', 'es_ES' => 'No se pudo enviar el correo de prueba SMTP. Comprueba el host, el puerto, el cifrado y los ajustes de autenticación.', 'ru_RU' => 'Не удалось отправить тестовое SMTP-письмо. Проверьте сервер, порт, шифрование и параметры аутентификации.', 'et' => 'SMTP test-e-kirja ei õnnestunud saata. Kontrolli serveri aadressi, porti, krüptimist ja autentimise seadeid.', 'de_DE' => 'Die SMTP-Test-E-Mail konnte nicht gesendet werden. Prüfen Sie Host, Port, Verschlüsselung und Authentifizierungseinstellungen.', 'fr_FR' => 'L’e-mail de test SMTP n’a pas pu être envoyé. Vérifiez l’hôte, le port, le chiffrement et les paramètres d’authentification.', 'da_DK' => 'SMTP-testmailen kunne ikke sendes. Kontroller vært, port, kryptering og godkendelsesindstillinger.', 'nl_NL' => 'SMTP-testmail kon niet worden verzonden. Controleer de host, poort, versleuteling en verificatie-instellingen.', 'sv_SE' => 'SMTP-testmeddelandet kunde inte skickas. Kontrollera värd, port, kryptering och autentiseringsinställningar.', 'fi' => 'SMTP-testisähköpostia ei voitu lähettää. Tarkista palvelin, portti, salaus ja todennusasetukset.', 'it_IT' => 'Impossibile inviare l’email di prova SMTP. Controlla host, porta, crittografia e impostazioni di autenticazione.', 'pt_PT' => 'Não foi possível enviar o email de teste SMTP. Verifique o servidor, a porta, a encriptação e as definições de autenticação.', 'pt_BR' => 'Não foi possível enviar o e-mail de teste SMTP. Verifique o servidor, a porta, a criptografia e as configurações de autenticação.', 'sk_SK' => 'Testovací e-mail SMTP sa nepodarilo odoslať. Skontrolujte hostiteľa, port, šifrovanie a nastavenia overenia.', 'pl_PL' => 'Nie udało się wysłać wiadomości testowej SMTP. Sprawdź host, port, szyfrowanie i ustawienia uwierzytelniania.', 'cs_CZ' => 'Testovací e-mail SMTP se nepodařilo odeslat. Zkontrolujte hostitele, port, šifrování a nastavení ověřování.', 'cs' => 'Testovací e-mail SMTP se nepodařilo odeslat. Zkontrolujte hostitele, port, šifrování a nastavení ověřování.', 'sl_SI' => 'Testnega e-poštnega sporočila SMTP ni bilo mogoče poslati. Preverite gostitelja, vrata, šifriranje in nastavitve preverjanja pristnosti.', 'hr_HR' => 'SMTP testnu e-poruku nije bilo moguće poslati. Provjerite poslužitelj, priključak, šifriranje i postavke autentifikacije.', 'ro_RO' => 'E-mailul de test SMTP nu a putut fi trimis. Verificați gazda, portul, criptarea și setările de autentificare.', 'hu_HU' => 'Az SMTP teszt e-mail nem küldhető el. Ellenőrizze a kiszolgáló, a port, a titkosítás és a hitelesítés beállításait.', 'bg_BG' => 'Тестовият SMTP имейл не можа да бъде изпратен. Проверете хоста, порта, шифроването и настройките за удостоверяване.', 'lt_LT' => 'SMTP bandomojo el. laiško išsiųsti nepavyko. Patikrinkite serverį, prievadą, šifravimą ir autentifikavimo nustatymus.', 'lv' => 'SMTP testa e-pastu neizdevās nosūtīt. Pārbaudiet servera, porta, šifrēšanas un autentifikācijas iestatījumus.', 'no_NO' => 'SMTP-test-e-posten kunne ikke sendes. Kontroller innstillingene for vert, port, kryptering og autentisering.', 'is_IS' => 'Ekki tókst að senda SMTP-prufutölvupóst. Athugaðu hýsil, gátt, dulkóðun og auðkenningarstillingar.', 'el' => 'Δεν ήταν δυνατή η αποστολή του δοκιμαστικού email SMTP. Ελέγξτε τον διακομιστή, τη θύρα, την κρυπτογράφηση και τις ρυθμίσεις ελέγχου ταυτότητας.', 'ga_IE' => 'Níorbh fhéidir an ríomhphost tástála SMTP a sheoladh. Seiceáil an t-óstach, an port, an criptiú agus socruithe fíordheimhnithe.', 'mt_MT' => 'L-email tat-test SMTP ma setgħetx tintbagħat. Iċċekkja l-host, il-port, l-encryption u s-settings tal-awtentikazzjoni.'],
            'emails.settings.calendar_invite_attachments_ics' => ['group' => 'emails', 'label' => 'Calendar invite attachments (ICS)', 'default' => 'Calendar invite attachments (ICS)', 'es_ES' => 'Archivos adjuntos de invitación de calendario (ICS)', 'ru_RU' => 'Вложения с приглашениями в календарь (ICS)', 'et' => 'Kalendrikutse manused (ICS)', 'de_DE' => 'Kalendereinladungen als Anhang (ICS)', 'fr_FR' => 'Pièces jointes d’invitation au calendrier (ICS)', 'da_DK' => 'Vedhæftede kalenderinvitationer (ICS)', 'nl_NL' => 'Bijlagen met agenda-uitnodigingen (ICS)', 'sv_SE' => 'Bilagor med kalenderinbjudningar (ICS)', 'fi' => 'Kalenterikutsujen liitteet (ICS)', 'it_IT' => 'Allegati invito calendario (ICS)', 'pt_PT' => 'Anexos de convite de calendário (ICS)', 'pt_BR' => 'Anexos de convite de calendário (ICS)', 'sk_SK' => 'Prílohy pozvánok do kalendára (ICS)', 'pl_PL' => 'Załączniki zaproszeń kalendarzowych (ICS)', 'cs_CZ' => 'Přílohy pozvánek do kalendáře (ICS)', 'cs' => 'Přílohy pozvánek do kalendáře (ICS)', 'sl_SI' => 'Priloge koledarskih vabil (ICS)', 'hr_HR' => 'Privici kalendarskih pozivnica (ICS)', 'ro_RO' => 'Atașamente cu invitații de calendar (ICS)', 'hu_HU' => 'Naptármeghívó-mellékletek (ICS)', 'bg_BG' => 'Прикачени календарни покани (ICS)', 'lt_LT' => 'Kalendoriaus kvietimų priedai (ICS)', 'lv' => 'Kalendāra ielūgumu pielikumi (ICS)', 'no_NO' => 'Vedlegg med kalenderinvitasjoner (ICS)', 'is_IS' => 'Viðhengi dagatalsboða (ICS)', 'el' => 'Συνημμένες προσκλήσεις ημερολογίου (ICS)', 'ga_IE' => 'Ceangaltáin cuireadh féilire (ICS)', 'mt_MT' => 'Annessi ta’ stedina tal-kalendarju (ICS)'],
            'emails.settings.attach_calendar_files_to_customer_booking_emails_so_clients_can_add_book' => ['group' => 'emails', 'label' => 'Attach calendar files to customer booking emails so clients can add bookings to Google Calendar, Apple Calendar, Outlook and other calendar apps.', 'default' => 'Attach calendar files to customer booking emails so clients can add bookings to Google Calendar, Apple Calendar, Outlook and other calendar apps.', 'es_ES' => 'Adjunta archivos de calendario a los correos de reserva de los clientes para que puedan añadir las reservas a Google Calendar, Apple Calendar, Outlook y otras aplicaciones de calendario.', 'ru_RU' => 'Прикреплять файлы календаря к письмам о бронировании, чтобы клиенты могли добавить бронирование в свой календарь.', 'et' => 'Lisa klientide broneeringukirjadele kalendrifailid, et nad saaksid broneeringud lisada Google Calendari, Apple Calendari, Outlooki ja teistesse kalendrirakendustesse.', 'de_DE' => 'Kalenderdateien an Buchungs-E-Mails für Kunden anhängen, damit sie Buchungen zu Google Kalender, Apple Kalender, Outlook und anderen Kalender-Apps hinzufügen können.', 'fr_FR' => 'Joignez des fichiers de calendrier aux e-mails de réservation des clients afin qu’ils puissent ajouter leurs réservations à Google Agenda, Apple Calendar, Outlook et d’autres applications de calendrier.', 'da_DK' => 'Vedhæft kalenderfiler til bookingmails, så kunder kan føje bookinger til Google Kalender, Apple Kalender, Outlook og andre kalenderapps.', 'nl_NL' => 'Voeg agendabestanden toe aan boekingsmails voor klanten, zodat zij boekingen kunnen toevoegen aan Google Agenda, Apple Agenda, Outlook en andere agenda-apps.', 'sv_SE' => 'Bifoga kalenderfiler till kundernas bokningsmeddelanden så att de kan lägga till bokningar i Google Kalender, Apple Kalender, Outlook och andra kalenderappar.', 'fi' => 'Liitä kalenteritiedostot asiakkaiden varaussähköposteihin, jotta asiakkaat voivat lisätä varaukset Google Calendariin, Apple Calendariin, Outlookiin ja muihin kalenterisovelluksiin.', 'it_IT' => 'Allega file di calendario alle email di prenotazione dei clienti, così potranno aggiungere le prenotazioni a Google Calendar, Apple Calendar, Outlook e altre app calendario.', 'pt_PT' => 'Anexe ficheiros de calendário aos emails de reserva dos clientes para que possam adicionar as reservas ao Google Calendar, Apple Calendar, Outlook e outras aplicações de calendário.', 'pt_BR' => 'Anexe arquivos de calendário aos e-mails de reserva dos clientes para que possam adicionar as reservas ao Google Calendar, Apple Calendar, Outlook e outras aplicações de calendário.', 'sk_SK' => 'Prikladať súbory kalendára k e-mailom zákazníkom o rezervácii, aby si mohli rezervácie pridať do Google Kalendára, Apple Kalendára, Outlooku a ďalších kalendárových aplikácií.', 'pl_PL' => 'Dołączaj pliki kalendarza do wiadomości e-mail z rezerwacją, aby klienci mogli dodawać rezerwacje do Kalendarza Google, Apple Calendar, Outlooka i innych aplikacji kalendarzowych.', 'cs_CZ' => 'Připojit soubory kalendáře k e-mailům zákazníků o rezervaci, aby si mohli přidat rezervace do Kalendáře Google, Apple Kalendáře, Outlooku a dalších kalendářových aplikací.', 'cs' => 'Připojit soubory kalendáře k e-mailům zákazníků o rezervaci, aby si mohli přidat rezervace do Kalendáře Google, Apple Kalendáře, Outlooku a dalších kalendářových aplikací.', 'sl_SI' => 'Koledarske datoteke priložite e-poštnim sporočilom strank o rezervaciji, da lahko stranke dodajo rezervacije v Google Calendar, Apple Calendar, Outlook in druge koledarske aplikacije.', 'hr_HR' => 'Priložite kalendarske datoteke e-porukama o rezervaciji kako bi klijenti mogli dodati rezervacije u Google Calendar, Apple Calendar, Outlook i druge kalendarske aplikacije.', 'ro_RO' => 'Atașați fișiere de calendar la e-mailurile de rezervare trimise clienților, astfel încât aceștia să poată adăuga rezervările în Google Calendar, Apple Calendar, Outlook și alte aplicații de calendar.', 'hu_HU' => 'Naptárfájlok csatolása az ügyfelek foglalási e-mailjeihez, hogy a foglalásokat hozzáadhassák a Google Naptárhoz, az Apple Naptárhoz, az Outlookhoz és más naptáralkalmazásokhoz.', 'bg_BG' => 'Прикачвайте календарни файлове към имейлите за резервации, за да могат клиентите да добавят резервациите в Google Calendar, Apple Calendar, Outlook и други календарни приложения.', 'lt_LT' => 'Pridėkite kalendoriaus failus prie klientų užsakymo el. laiškų, kad jie galėtų įtraukti užsakymus į „Google Calendar“, „Apple Calendar“, „Outlook“ ir kitas kalendoriaus programas.', 'lv' => 'Pievienojiet kalendāra failus klientu rezervāciju e-pastiem, lai klienti varētu pievienot rezervācijas Google Calendar, Apple Calendar, Outlook un citām kalendāra lietotnēm.', 'no_NO' => 'Legg ved kalenderfiler i bestillings-e-poster, slik at kundene kan legge bestillinger til i Google Kalender, Apple Kalender, Outlook og andre kalenderapper.', 'is_IS' => 'Hengdu dagatalsskrár við bókunarpósta til viðskiptavina svo þeir geti bætt bókunum við Google Calendar, Apple Calendar, Outlook og önnur dagatalsforrit.', 'el' => 'Επισυνάψτε αρχεία ημερολογίου στα email κρατήσεων πελατών, ώστε να μπορούν να προσθέσουν τις κρατήσεις στο Google Calendar, Apple Calendar, Outlook και άλλες εφαρμογές ημερολογίου.', 'ga_IE' => 'Ceangail comhaid féilire le ríomhphoist áirithinte custaiméirí ionas gur féidir le cliaint áirithintí a chur le Google Calendar, Apple Calendar, Outlook agus aipeanna féilire eile.', 'mt_MT' => 'Ehmeż fajls tal-kalendarju mal-emails tal-prenotazzjoni tal-klijenti sabiex ikunu jistgħu jżidu l-prenotazzjonijiet ma’ Google Calendar, Apple Calendar, Outlook u apps oħra tal-kalendarju.'],
