            'emails.settings.attach_ics_calendar_invites_to_customer_booking_emails_and_reminders' => ['group' => 'emails', 'label' => 'Attach ICS calendar invites to customer booking emails and reminders', 'default' => 'Attach ICS calendar invites to customer booking emails and reminders', 'es_ES' => 'Adjuntar invitaciones de calendario ICS a los correos de reserva y recordatorios de los clientes', 'ru_RU' => 'Прикреплять приглашения ICS к письмам о бронировании и напоминаниям для клиентов.', 'et' => 'Lisa ICS-kalendrikutsed klientide broneeringukirjadele ja meeldetuletustele', 'de_DE' => 'ICS-Kalendereinladungen an Buchungs-E-Mails und Erinnerungen für Kunden anhängen', 'fr_FR' => 'Joindre des invitations de calendrier ICS aux e-mails de réservation et aux rappels destinés aux clients', 'da_DK' => 'Vedhæft ICS-kalenderinvitationer til bookingmails og påmindelser til kunder', 'nl_NL' => 'Voeg ICS-agenda-uitnodigingen toe aan boekingsmails en herinneringen voor klanten', 'sv_SE' => 'Bifoga ICS-kalenderinbjudningar till kundernas bokningsmeddelanden och påminnelser', 'fi' => 'Liitä ICS-kalenterikutsut asiakkaiden varaussähköposteihin ja muistutuksiin', 'it_IT' => 'Allega inviti calendario ICS alle email di prenotazione e ai promemoria dei clienti', 'pt_PT' => 'Anexar convites de calendário ICS aos emails de reserva e lembretes enviados aos clientes', 'pt_BR' => 'Anexar convites de calendário ICS aos e-mails de reserva e lembretes enviados aos clientes', 'sk_SK' => 'Prikladať pozvánky ICS do kalendára k e-mailom zákazníkom o rezervácii a pripomienkam', 'pl_PL' => 'Dołączaj zaproszenia kalendarzowe ICS do wiadomości e-mail z rezerwacją i przypomnień dla klientów', 'cs_CZ' => 'Připojit pozvánky ICS k e-mailům zákazníků o rezervaci a připomínkám', 'cs' => 'Připojit pozvánky ICS k e-mailům zákazníků o rezervaci a připomínkám', 'sl_SI' => 'Priloži koledarska vabila ICS e-poštnim sporočilom strank o rezervacijah in opomnikom', 'hr_HR' => 'Priloži ICS kalendarske pozivnice e