            'emails.test.save_smtp_settings_first_then_send_a_test_email_to_confirm_delivery' => ['group' => 'emails', 'label' => 'Save SMTP settings first, then send a test email to confirm delivery.', 'default' => 'Save SMTP settings first, then send a test email to confirm delivery.', 'es_ES' => 'Guarda primero los ajustes SMTP y después envía un correo de prueba para confirmar la entrega.', 'ru_RU' => 'Сначала сохраните настройки SMTP, затем отправьте тестовое письмо, чтобы проверить доставку.', 'et' => 'Salvesta esmalt SMTP sätted ja seejärel saada kohaletoimetamise kontrollimiseks testkiri.', 'de_DE' => 'Speichern Sie zuerst die SMTP-Einstellungen und senden Sie anschließend eine Test-E-Mail, um die Zustellung zu bestätigen.', 'fr_FR' => 'Enregistrez d’abord les paramètres SMTP, puis envoyez un e-mail de test pour confirmer la distribution.', 'da_DK' => 'Gem først SMTP-indstillingerne, og send derefter en testmail for at bekræfte leveringen.', 'nl_NL' => 'Sla eerst de SMTP-instellingen op en verzend daarna een testmail om de bezorging te controleren.', 'sv_SE' => 'Spara först SMTP-inställningarna och skicka sedan ett testmeddelande för att bekräfta leveransen.', 'fi' => 'Tallenna ensin SMTP-asetukset ja lähetä sitten testisähköposti toimituksen varmistamiseksi.', 'it_IT' => 'Salva prima le impostazioni SMTP, quindi invia un’email di prova per verificare la consegna.', 'pt_PT' => 'Guarde primeiro as definições SMTP e, em seguida, envie um email de teste para confirmar a entrega.', 'pt_BR' => 'Guarde primeiro as configurações SMTP e, depois, envie um e-mail de teste para confirmar a entrega.', 'sk_SK' => 'Najprv uložte nastavenia SMTP a potom odošlite testovací e-mail na potvrdenie doručenia.', 'pl_PL' => 'Najpierw zapisz ustawienia SMTP, a następnie wyślij wiadomość testową, aby potwierdzić dostarczanie.', 'cs_CZ' => 'Nejprve uložte nastavení SMTP a poté odešlete testovací e-mail pro ověření doručení.', 'cs' => 'Nejprve uložte nastavení SMTP a poté odešlete tes