            'emails.settings.admin_notification_email' => ['group' => 'emails', 'label' => 'Admin notification email', 'default' => 'Admin notification email', 'es_ES' => 'Correo de notificaciones del administrador', 'bg_BG' => 'Имейл за админ известия', 'ru_RU' => 'Email администратора для уведомлений', 'fr_FR' => 'E-mail de notification admin', 'de_DE' => 'Admin neintification E-Mail', 'et' => 'Admin notification e-post', 'da_DK' => 'E-mail til administratornotifikationer', 'nl_NL' => 'E-mailadres voor beheerdersmeldingen', 'sv_SE' => 'E-postadress för administratörsaviseringar', 'fi' => 'Ylläpitäjän ilmoitussähköposti', 'it_IT' => 'Email di notifica amministratore', 'pt_PT' => 'Email de notificações do administrador', 'pt_BR' => 'E-mail de notificações do administrador', 'sk_SK' => 'E-mail pre oznámenia správcu', 'pl_PL' => 'Adres e-mail powiadomień administratora', 'cs_CZ' => 'E-mail pro oznámení správci', 'cs' => 'E-mail pro oznámení správci', 'sl_SI' => 'E-poštni naslov za obvestila skrbnika', 'hr_HR' => 'E-adresa za obavijesti administratora', 'ro_RO' => 'E-mail pentru notificările administratorului', 'hu_HU' => 'Adminisztrátori értesítési e-mail-cím', 'lt_LT' => 'Administratoriaus pranešimų el. paštas', 'lv' => 'Administratora paziņojumu e-pasts', 'no_NO' => 'E-postadresse for administratorvarsler', 'is_IS' => 'Netfang fyrir tilkynningar stjórnanda', 'el' => 'Email ειδοποιήσεων διαχειριστή', 'ga_IE' => 'Ríomhphost fógraí an riarthóra', 'mt_MT' => 'Email għan-notifiki tal-amministratur'],
        ];

        // Registry selectors expose Croatian as the short locale `hr`, while
        // WordPress/gettext and template catalogs use the canonical `hr_HR`.
        // Keep both keys synchronized so runtime lookup, the translation editor,
        // readiness scanning and strict freeze validation all inspect the same data.
        foreach ($strings as &$meta) {
            if (isset($meta['hr_HR']) && !isset($meta['hr'])) {
                $meta['hr'] = $meta['hr_HR'];
            }
        }
        unset($meta);

        return $strings;
    }
}
